namespace Aurora {
public static class DailyMaintenance {
    public static string Root{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"AuroraMaintenance");}}
    public static void ProtectRoot(){string path=Root;if(Directory.Exists(path)&&(File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new IOException("Managed folder cannot be a reparse point");Directory.CreateDirectory(path);DirectorySecurity acl=new DirectorySecurity();acl.SetAccessRuleProtection(true,false);acl.SetOwner(new SecurityIdentifier(WellKnownSidType.BuiltinAdministratorsSid,null));foreach(WellKnownSidType sid in new[]{WellKnownSidType.BuiltinAdministratorsSid,WellKnownSidType.LocalSystemSid})acl.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(sid,null),FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));new DirectoryInfo(path).SetAccessControl(acl);}
    public static string Script(string mode,string sid){if(!new[]{"Registry","Restore"}.Contains(mode)||!Regex.IsMatch(sid??"","^S-1-5(-[0-9]+)+$"))throw new ArgumentException("Invalid maintenance parameters");string script=File.ReadAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"assets","Maintenance.ps1"));return script.Replace("__MODE__",mode).Replace("__ROOT__",Root.Replace("'","''")).Replace("__SID__",sid);}
    public static string Time(string time){DateTime value;if(!DateTime.TryParseExact(time,"HH:mm",System.Globalization.CultureInfo.InvariantCulture,System.Globalization.DateTimeStyles.None,out value))throw new ArgumentException(L.T("Informe o horário como HH:mm.","Enter time as HH:mm."));return value.ToString("HH:mm");}
    public static XDocument TaskXml(string mode,string time,string sid){Time(time);XNamespace ns="http://schemas.microsoft.com/windows/2004/02/mit/task";string script=Script(mode,sid);return new XDocument(new XElement(ns+"Task",new XAttribute("version","1.2"),new XElement(ns+"RegistrationInfo",new XElement(ns+"Description","Aurora daily "+mode+" maintenance")),new XElement(ns+"Triggers",new XElement(ns+"CalendarTrigger",new XElement(ns+"StartBoundary",DateTime.Now.ToString("yyyy-MM-dd")+"T"+time+":00"),new XElement(ns+"Enabled","true"),new XElement(ns+"ScheduleByDay",new XElement(ns+"DaysInterval","1")))),new XElement(ns+"Principals",new XElement(ns+"Principal",new XAttribute("id","System"),new XElement(ns+"UserId","S-1-5-18"),new XElement(ns+"RunLevel","HighestAvailable"))),new XElement(ns+"Settings",new XElement(ns+"MultipleInstancesPolicy","IgnoreNew"),new XElement(ns+"DisallowStartIfOnBatteries","false"),new XElement(ns+"StopIfGoingOnBatteries","false"),new XElement(ns+"StartWhenAvailable","true"),new XElement(ns+"Enabled","true"),new XElement(ns+"ExecutionTimeLimit","PT2H")),new XElement(ns+"Actions",new XAttribute("Context","System"),new XElement(ns+"Exec",new XElement(ns+"Command",Path.Combine(Environment.SystemDirectory,"WindowsPowerShell","v1.0","powershell.exe")),new XElement(ns+"Arguments","-NoProfile -NonInteractive -EncodedCommand "+Convert.ToBase64String(Encoding.Unicode.GetBytes(script)))))));}
    public static string Register(string mode,string time,string sid){
        ProtectRoot();string name=mode=="Registry"?"Aurora-Registry-Daily":"Aurora-RestorePoint-Daily";
        string xml=TaskXml(mode,time,sid).ToString(SaveOptions.DisableFormatting);
        // Avoid passing the large task definition through nested encoded command lines.
        string definition=Path.Combine(Root,"task-"+Guid.NewGuid().ToString("N")+".xml");
        File.WriteAllText(definition,xml,new UTF8Encoding(false));
        string script="$name="+Runner.QuotePS(name)+"; $expected="+Runner.QuotePS(Time(time))+"; $xml=[IO.File]::ReadAllText("+Runner.QuotePS(definition)+",[Text.Encoding]::UTF8); "+
            "$service=New-Object -ComObject Schedule.Service; $service.Connect(); $folder=$service.GetFolder('\\'); "+
            "[void]$folder.RegisterTask($name,$xml,6,'SYSTEM',$null,5,$null); $task=$folder.GetTask($name); "+
            "if(-not $task.Enabled){throw 'Registered task is disabled'}; [xml]$readback=$task.Xml; "+
            "$ns=New-Object System.Xml.XmlNamespaceManager($readback.NameTable); $ns.AddNamespace('t','http://schemas.microsoft.com/windows/2004/02/mit/task'); "+
            "$start=$readback.SelectSingleNode('//t:StartBoundary',$ns); if(-not $start -or -not $start.InnerText.Contains('T'+$expected+':')){throw 'Registered task time differs from requested time'}; "+
            "Write-Output ('OK • '+$name+' • '+$expected+' • "+L.T("agenda criada e verificada","schedule registered and verified")+"'); Write-Output ('"+L.T("Próxima execução: ","Next run: ")+"'+$task.NextRunTime)";
        try{var r=Runner.PS(script,30000);if(r.Code!=0)throw new IOException(r.Output);return r.Output;}
        finally{try{File.Delete(definition);}catch{}}
    }
    public static string Remove(string mode){string name=mode=="Registry"?"Aurora-Registry-Daily":"Aurora-RestorePoint-Daily";var query=Runner.Run("schtasks.exe","/Query /TN "+Args.Q(name),15000);if(query.Code!=0)return L.T("Agenda não encontrada: ","Schedule not found: ")+name;var r=Runner.Run("schtasks.exe","/Delete /TN "+Args.Q(name)+" /F",15000);if(r.Code!=0)throw new IOException(r.Output);return r.Output;}
}
