        var schedules=Card(T("Agendas diárias","Daily schedules"),T("As tarefas executam como SYSTEM, com comandos embutidos no Agendador e backups em pasta protegida de administrador. Não dependem de scripts editáveis no perfil do usuário.","Tasks run as SYSTEM, with embedded scheduler commands and backups in an administrator-protected folder. They do not depend on editable scripts in the user profile."));CheckBox registry=Choice(schedules,T("Backup diário do Registro","Daily registry backup"),true,false);TextBox regTime=TimeField(schedules,T("Horário local do backup (HH:mm)","Local backup time (HH:mm)"),"09:00");CheckBox restore=Choice(schedules,T("Ponto de restauração diário","Daily system restore point"),true,false);TextBox restoreTime=TimeField(schedules,T("Horário local da restauração (HH:mm)","Local restore point time (HH:mm)"),"09:15");Note(schedules,"Ao aplicar, opções marcadas criam/atualizam a agenda; desmarcadas removem apenas as tarefas do OuO. Backups existentes são preservados. O Windows pode limitar pontos de restauração a um por 24 horas.","Applying creates/updates checked schedules; unchecked options remove only OuO tasks. Existing backups are preserved. Windows may limit restore points to one every 24 hours.");
        TextBox taskOut=Input("");taskOut.IsReadOnly=true;taskOut.Foreground=StateGreen;taskOut.TextChanged+=(sender,args)=>taskOut.Foreground=OutcomeBrush(taskOut.Text);taskOut.AcceptsReturn=true;taskOut.Height=180;taskOut.VerticalScrollBarVisibility=ScrollBarVisibility.Auto;
        Row(schedules,Button(T("Aplicar agendas","Apply schedules"),()=>{if(repairRunning||!RequireAdmin())return;bool reg=registry.IsChecked==true,res=restore.IsChecked==true;string rt,st;try{rt=DailyMaintenance.Time(regTime.Text);st=DailyMaintenance.Time(restoreTime.Text);}catch(Exception e){ShowNotice(e.Message);return;}string sid=WindowsIdentity.GetCurrent().User.Value;if(!Confirm(T("Agendas do OuO:\nBackup do Registro: ","OuO schedules:\nRegistry backup: ")+(reg?rt:T("remover agenda","remove schedule"))+T("\nPonto de restauração: ","\nRestore point: ")+(res?st:T("remover agenda","remove schedule"))+T("\n\nA agenda de Registro salva as colmeias do sistema e o perfil desta conta quando ele estiver carregado. Retenção: 14 dias. Proteção do Sistema deve estar habilitada para criar pontos.","\n\nRegistry scheduling saves system hives and this account's profile when loaded. Retention: 14 days. System Protection must be enabled to create restore points.")))return;Work("Daily maintenance schedules",()=>{var result=new List<string>();foreach(string mode in new[]{"Registry","Restore"})try{bool enabled=mode=="Registry"?reg:res;result.Add(enabled?DailyMaintenance.Register(mode,mode=="Registry"?rt:st,sid):DailyMaintenance.Remove(mode));}catch(Exception ex){result.Add("ERROR • "+mode+" • "+ex.Message);}return String.Join("\n\n",result);},r=>taskOut.Text=r);}),Button(T("Consultar agendas","Inspect schedules"),()=>{if(!RequireAdmin())return;List<ScheduleState> inspected=null;Work("Inspect schedules",()=>{inspected=ProtectionStatus.Schedules();return String.Join("\n\n",inspected.Select(x=>x.ToString()).ToArray());},r=>{taskOut.Text=r;if(inspected!=null)foreach(var item in inspected){if(item.Mode=="Registry"){registry.IsChecked=item.Exists&&item.Enabled;if(item.Exists)regTime.Text=item.Time;}else{restore.IsChecked=item.Exists&&item.Enabled;if(item.Exists)restoreTime.Text=item.Time;}}});}));AttachResult(schedules,taskOut);
        var immediate=Card(T("Backup e proteção agora","Backup & protection now"),T("Backups binários do Registro não substituem uma cópia dos seus arquivos. A restauração integral das colmeias é um procedimento de recuperação e não é automatizada pelo OuO.","Binary registry backups do not replace personal file backups. Full hive restoration is a recovery procedure and is not automated by OuO."));CheckBox backNow=Choice(immediate,T("Salvar Registro agora","Back up registry now"),true,false),pointNow=Choice(immediate,T("Criar ponto de restauração agora","Create a restore point now"),true,false),protect=Choice(immediate,T("Habilitar Proteção do Sistema na unidade Windows","Enable System Protection on the Windows drive"),true,false);TextBox immediateOut=Input("");immediateOut.IsReadOnly=true;immediateOut.Foreground=StateGreen;immediateOut.TextChanged+=(sender,args)=>immediateOut.Foreground=OutcomeBrush(immediateOut.Text);immediateOut.AcceptsReturn=true;immediateOut.Height=180;immediateOut.VerticalScrollBarVisibility=ScrollBarVisibility.Auto;
